# owner: platform
"""Seating rows for students, ordered by last name."""

from typing import List

from rosterkit.models import Student

# ---
def seating_rows(
    students: List[Student], seats_per_row: int
) -> List[str]:
    """One line per row, students sorted by last name."""
    _check_input(students, seats_per_row)
    ordered = sorted(
        students, key=lambda item: item.last_name
    )
    return _format_rows(_chunk(ordered, seats_per_row))

def _check_input(
    students: List[Student], seats_per_row: int
) -> None:
    if seats_per_row <= 0:
        raise ValueError(f"bad seat count {seats_per_row}")
    if not students:
        raise ValueError("no students to seat")

def _chunk(
    students: List[Student], size: int
) -> List[List[Student]]:
    return [
        students[start:start + size]
        for start in range(0, len(students), size)
    ]

def _format_rows(groups: List[List[Student]]) -> List[str]:
    lines = []
    for number, group in enumerate(groups, 1):
        names = [student.display_name for student in group]
        lines.append(f"Row {number}: {' | '.join(names)}")
    return lines

